-- ─────────────────────────────────────────────
-- FixASN LMS Database Schema (v2 — camelCase)
-- Run in Supabase SQL Editor
--
-- ID convention:
--   Master/reference tables → SERIAL (auto-increment int)
--   Transactional tables    → UUID (generated by uuid_generate_v7())
--   Junction tables         → SERIAL (auto-increment int)
-- ─────────────────────────────────────────────

-- Enable UUID extension + v7 generator
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- UUID v7 generator (time-ordered, sortable)
CREATE OR REPLACE FUNCTION uuid_generate_v7()
RETURNS uuid
LANGUAGE plpgsql
AS $$
DECLARE
    unix_ts_ms BIGINT;
    uuid_bytes BYTEA;
BEGIN
    unix_ts_ms := floor(extract(epoch FROM clock_timestamp()) * 1000);
    uuid_bytes := gen_random_bytes(16);

    -- Set timestamp bytes (0-5, big endian)
    uuid_bytes := set_byte(uuid_bytes, 0, ((unix_ts_ms >> 40) & 255)::int);
    uuid_bytes := set_byte(uuid_bytes, 1, ((unix_ts_ms >> 32) & 255)::int);
    uuid_bytes := set_byte(uuid_bytes, 2, ((unix_ts_ms >> 24) & 255)::int);
    uuid_bytes := set_byte(uuid_bytes, 3, ((unix_ts_ms >> 16) & 255)::int);
    uuid_bytes := set_byte(uuid_bytes, 4, ((unix_ts_ms >> 8) & 255)::int);
    uuid_bytes := set_byte(uuid_bytes, 5, (unix_ts_ms & 255)::int);

    -- Set version bits (byte 6: 0111xxxx = 0x70-0x7F)
    uuid_bytes := set_byte(uuid_bytes, 6, (get_byte(uuid_bytes, 6) & 0x0F | 0x70)::int);

    -- Set variant bits (byte 8: 10xxxxxx = 0x80-0xBF)
    uuid_bytes := set_byte(uuid_bytes, 8, (get_byte(uuid_bytes, 8) & 0x3F | 0x80)::int);

    RETURN encode(uuid_bytes, 'hex')::uuid;
END;
$$;

-- ─────────────────────────────────────────────
-- USERS
-- ─────────────────────────────────────────────
CREATE TABLE users (
  id          SERIAL PRIMARY KEY,
  email       TEXT UNIQUE NOT NULL,
  name        TEXT NOT NULL,
  avatar      TEXT,
  role        TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),
  createdAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  createdBy   TEXT,
  createdIP   TEXT,
  updatedAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedBy   TEXT,
  updatedIP   TEXT,
  deletedAt   TIMESTAMPTZ
);

-- ─────────────────────────────────────────────
-- PERMISSIONS (granular access control)
-- ─────────────────────────────────────────────
CREATE TABLE permissions (
  id          SERIAL PRIMARY KEY,
  name        TEXT UNIQUE NOT NULL,
  description TEXT,
  category    TEXT NOT NULL DEFAULT 'general',
  createdAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedAt   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ─────────────────────────────────────────────
-- ROLE_PERMISSIONS (maps roles to permissions)
-- ─────────────────────────────────────────────
CREATE TABLE rolePermissions (
  id             SERIAL PRIMARY KEY,
  role           TEXT NOT NULL CHECK (role IN ('user', 'admin')),
  permissionId   INTEGER NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,
  createdAt      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedAt      TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(role, permissionId)
);

-- ─────────────────────────────────────────────
-- USER_PERMISSIONS (override permissions for specific users)
-- ─────────────────────────────────────────────
CREATE TABLE userPermissions (
  id             SERIAL PRIMARY KEY,
  userId         INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  permissionId   INTEGER NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,
  isGranted      BOOLEAN NOT NULL DEFAULT true,
  createdAt      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedAt      TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(userId, permissionId)
);

-- ─────────────────────────────────────────────
-- PACKAGES
-- ─────────────────────────────────────────────
CREATE TABLE packages (
  id            SERIAL PRIMARY KEY,
  name          TEXT UNIQUE NOT NULL,
  tryoutCount   INTEGER NOT NULL DEFAULT 0,
  price         INTEGER NOT NULL DEFAULT 0,
  description   TEXT NOT NULL DEFAULT '',
  isTrial       BOOLEAN NOT NULL DEFAULT false,
  isActive      BOOLEAN NOT NULL DEFAULT true,
  createdAt     TIMESTAMPTZ NOT NULL DEFAULT now(),
  createdBy     TEXT,
  createdIP     TEXT,
  updatedAt     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedBy     TEXT,
  updatedIP     TEXT,
  deletedAt     TIMESTAMPTZ
);

-- ─────────────────────────────────────────────
-- TRYOUTS
-- ─────────────────────────────────────────────
CREATE TABLE tryouts (
  id          SERIAL PRIMARY KEY,
  name        TEXT NOT NULL,
  isTrial     BOOLEAN NOT NULL DEFAULT false,
  sortOrder   INTEGER NOT NULL DEFAULT 0,
  createdAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  createdBy   TEXT,
  createdIP   TEXT,
  updatedAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedBy   TEXT,
  updatedIP   TEXT,
  deletedAt   TIMESTAMPTZ
);

-- ─────────────────────────────────────────────
-- PACKAGE_TRYOUTS (M2M)
-- ─────────────────────────────────────────────
CREATE TABLE packageTryouts (
  id          SERIAL PRIMARY KEY,
  packageId   INTEGER NOT NULL REFERENCES packages(id) ON DELETE CASCADE,
  tryoutId    INTEGER NOT NULL REFERENCES tryouts(id) ON DELETE CASCADE,
  createdAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(packageId, tryoutId)
);

-- ─────────────────────────────────────────────
-- QUESTIONS
-- ─────────────────────────────────────────────
CREATE TABLE questions (
  id               SERIAL PRIMARY KEY,
  category         TEXT NOT NULL CHECK (category IN ('TWK', 'TIU', 'TKP')),
  question         TEXT NOT NULL,
  questionImage    TEXT,
  correctAnswer    INTEGER,
  explanation      TEXT,
  explanationImage TEXT,
  createdAt        TIMESTAMPTZ NOT NULL DEFAULT now(),
  createdBy        TEXT,
  createdIP        TEXT,
  updatedAt        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedBy        TEXT,
  updatedIP        TEXT,
  deletedAt        TIMESTAMPTZ
);

-- ─────────────────────────────────────────────
-- QUESTION_OPTIONS
-- ─────────────────────────────────────────────
CREATE TABLE questionOptions (
  id            SERIAL PRIMARY KEY,
  questionId    INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
  optionIndex   INTEGER NOT NULL CHECK (optionIndex BETWEEN 0 AND 4),
  optionText    TEXT,
  optionImage   TEXT,
  tkpValue      INTEGER,
  createdAt     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedAt     TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(questionId, optionIndex)
);

-- ─────────────────────────────────────────────
-- TRYOUT_QUESTIONS (M2M)
-- ─────────────────────────────────────────────
CREATE TABLE tryoutQuestions (
  id          SERIAL PRIMARY KEY,
  tryoutId    INTEGER NOT NULL REFERENCES tryouts(id) ON DELETE CASCADE,
  questionId  INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
  sortOrder   INTEGER NOT NULL DEFAULT 0,
  createdAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(tryoutId, questionId)
);

-- ─────────────────────────────────────────────
-- BANK_ACCOUNTS
-- ─────────────────────────────────────────────
CREATE TABLE bankAccounts (
  id            SERIAL PRIMARY KEY,
  bankName      TEXT NOT NULL,
  accountNumber TEXT NOT NULL,
  accountHolder TEXT NOT NULL,
  isActive      BOOLEAN NOT NULL DEFAULT true,
  createdAt     TIMESTAMPTZ NOT NULL DEFAULT now(),
  createdBy     TEXT,
  createdIP     TEXT,
  updatedAt     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedBy     TEXT,
  updatedIP     TEXT,
  deletedAt     TIMESTAMPTZ,
  UNIQUE(bankName, accountNumber)
);

-- ─────────────────────────────────────────────
-- PAYMENTS
-- ─────────────────────────────────────────────
CREATE TABLE payments (
  id          UUID PRIMARY KEY DEFAULT uuid_generate_v7(),
  userId      TEXT NOT NULL REFERENCES users(email),
  packageId   INTEGER NOT NULL REFERENCES packages(id),
  status      TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'blocked')),
  proofUrl    TEXT,
  blockReason TEXT,
  createdAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  createdBy   TEXT,
  createdIP   TEXT,
  updatedAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedBy   TEXT,
  updatedIP   TEXT,
  deletedAt   TIMESTAMPTZ
);

-- ─────────────────────────────────────────────
-- USER_PURCHASES
-- ─────────────────────────────────────────────
CREATE TABLE userPurchases (
  id          UUID NOT NULL DEFAULT uuid_generate_v7(),
  userId      TEXT NOT NULL REFERENCES users(email),
  packageId   INTEGER NOT NULL REFERENCES packages(id),
  paymentId   UUID REFERENCES payments(id),
  createdAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  createdBy   TEXT,
  createdIP   TEXT,
  updatedAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedBy   TEXT,
  updatedIP   TEXT,
  deletedAt   TIMESTAMPTZ,
  PRIMARY KEY (id),
  UNIQUE(userId, packageId)
);

-- ─────────────────────────────────────────────
-- TRYOUT_ATTEMPTS
-- ─────────────────────────────────────────────
CREATE TABLE tryoutAttempts (
  id          UUID PRIMARY KEY DEFAULT uuid_generate_v7(),
  userId      TEXT NOT NULL REFERENCES users(email),
  userName    TEXT NOT NULL,
  tryoutId    INTEGER NOT NULL REFERENCES tryouts(id) ON DELETE CASCADE,
  twkScore    INTEGER NOT NULL DEFAULT 0,
  tiuScore    INTEGER NOT NULL DEFAULT 0,
  tkpScore    INTEGER NOT NULL DEFAULT 0,
  totalScore  INTEGER NOT NULL DEFAULT 0,
  createdAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  createdBy   TEXT,
  createdIP   TEXT,
  updatedAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedBy   TEXT,
  updatedIP   TEXT,
  deletedAt   TIMESTAMPTZ
);

-- ─────────────────────────────────────────────
-- ATTEMPT_ANSWERS
-- ─────────────────────────────────────────────
CREATE TABLE attemptAnswers (
  id              UUID PRIMARY KEY DEFAULT uuid_generate_v7(),
  attemptId       UUID NOT NULL REFERENCES tryoutAttempts(id) ON DELETE CASCADE,
  questionIndex   INTEGER NOT NULL,
  selectedOption  INTEGER NOT NULL DEFAULT -1,
  createdAt       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedAt       TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(attemptId, questionIndex)
);

-- ─────────────────────────────────────────────
-- LOGO_CONFIG_ENTRIES
-- ─────────────────────────────────────────────
CREATE TABLE logoConfigEntries (
  id          SERIAL PRIMARY KEY,
  configKey   TEXT UNIQUE NOT NULL,
  configValue TEXT,
  createdAt   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updatedAt   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ─────────────────────────────────────────────
-- TRIGGER: auto-update updatedAt
-- ─────────────────────────────────────────────
CREATE OR REPLACE FUNCTION updateUpdatedAt()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updatedAt = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_users_updatedAt         BEFORE UPDATE ON users          FOR EACH ROW EXECUTE FUNCTION updateUpdatedAt();
CREATE TRIGGER trg_packages_updatedAt      BEFORE UPDATE ON packages       FOR EACH ROW EXECUTE FUNCTION updateUpdatedAt();
CREATE TRIGGER trg_tryouts_updatedAt       BEFORE UPDATE ON tryouts        FOR EACH ROW EXECUTE FUNCTION updateUpdatedAt();
CREATE TRIGGER trg_questions_updatedAt     BEFORE UPDATE ON questions      FOR EACH ROW EXECUTE FUNCTION updateUpdatedAt();
CREATE TRIGGER trg_payments_updatedAt      BEFORE UPDATE ON payments       FOR EACH ROW EXECUTE FUNCTION updateUpdatedAt();
CREATE TRIGGER trg_logoConfigEntries_updatedAt BEFORE UPDATE ON logoConfigEntries FOR EACH ROW EXECUTE FUNCTION updateUpdatedAt();
CREATE TRIGGER trg_tryoutAttempts_updatedAt BEFORE UPDATE ON tryoutAttempts FOR EACH ROW EXECUTE FUNCTION updateUpdatedAt();
CREATE TRIGGER trg_bankAccounts_updatedAt  BEFORE UPDATE ON bankAccounts   FOR EACH ROW EXECUTE FUNCTION updateUpdatedAt();

